-- Lane A (foundation): interface roles, rule origins, sysctls, policy-routing
-- hook and config revisions.

-- Logical role of an interface: 'wan', 'lan', or 'opt<N>'. Firewall/NAT
-- rules reference roles as '@wan' / '@lan' / '@opt1' instead of device names;
-- the firewall applier resolves them at apply time, so re-assigning a NIC
-- never leaves rules pointing at the old device. NULL = unassigned.
ALTER TABLE interfaces ADD COLUMN role TEXT;
CREATE INDEX IF NOT EXISTS idx_interfaces_role ON interfaces(role);

-- Who owns a rule:
--   'system'  - generated by Patronus itself (anti-lockout). Never deletable
--               through the API/UI; the applier always enforces it.
--   'default' - seeded once on first boot (allow LAN to any, outbound
--               masquerade). Editable and deletable; never re-seeded.
--   'user'    - created through the UI/API/CLI.
--   'gitops'  - owned by the declarative apply engine, keyed by `name`.
ALTER TABLE firewall_rules ADD COLUMN origin TEXT NOT NULL DEFAULT 'user';
ALTER TABLE nat_rules ADD COLUMN origin TEXT NOT NULL DEFAULT 'user';

-- Policy-routing hook (contract between lane B and lane E): name of a
-- gateway or gateway group that matching traffic is routed through. Lane E
-- owns the gateway tables and resolves the name to an fwmark; lane B renders
-- `meta mark set <mark>` for rules that carry it. NULL = main routing table.
ALTER TABLE firewall_rules ADD COLUMN gateway TEXT;

-- Kernel sysctls applied in the first boot phase. Keys use sysctl(8) dotted
-- notation ('net.ipv4.ip_forward'). As in sysctl(8), a '.' inside one
-- component (a VLAN device such as eth0.100) is written as '/':
-- 'net.ipv6.conf.eth0/100.accept_ra'.
CREATE TABLE IF NOT EXISTS sysctls (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL,
    origin TEXT NOT NULL DEFAULT 'user',
    updated_at INTEGER NOT NULL
);

-- Snapshot of the whole store taken before every change set (config
-- history / rollback). `config_json` is ConfigStore::export_json().
CREATE TABLE IF NOT EXISTS config_revisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at INTEGER NOT NULL,
    user TEXT NOT NULL DEFAULT 'system',
    summary TEXT NOT NULL,
    config_json TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_config_revisions_created ON config_revisions(created_at DESC);
